// Regenerates site/firmware.js from the built firmware binaries.
// Usage: node tools/make_firmware.mjs
import { readFileSync, writeFileSync } from 'fs';
import { fileURLToPath } from 'url';

const root = fileURLToPath(new URL('..', import.meta.url));
const firmwares = [
    ['eth_http', 'eth_http/eth_http.bin', 'eth_http.bin'],
    ['eth_dhcp', 'eth_dhcp/eth_dhcp.bin', 'eth_dhcp.bin'],
    ['eth_test', 'eth_test/eth_test.bin', 'eth_test.bin'],
    ['blinky', 'blinky/blinky.bin', 'blinky.bin'],
];

const lines = [
    '// Generated by tools/make_firmware.mjs — do not edit',
    '// Embedded firmware binaries for the in-browser demo.',
    'export const FIRMWARES = {',
];
for (const [key, path, name] of firmwares) {
    const bytes = readFileSync(root + path);
    lines.push(`  ${key}: { name: ${JSON.stringify(name)}, bytes: ${JSON.stringify(bytes.toString('base64'))} },`);
}
lines.push('};');
writeFileSync(root + 'site/firmware.js', lines.join('\n') + '\n');
console.log('wrote site/firmware.js');
